    public IActionResult NotAnAction() => Ok();

    [HttpGet("generic")]
    public IActionResult Generic<T>() => Ok();

    [HttpGet("private")]
    private IActionResult Private() => Ok();

    [HttpGet("static")]
    public static IActionResult Static() => new OkResult();
}

